<script module lang="ts">
/**
 * A picture opened large over the page (`design/components/lightbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/lightbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/dialog'
import { useMachine } from '@zag-js/svelte'

import {
  Portal,
  SlotOutlet,
  SlotScope,
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  modalFocusTarget,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/lightbox.module.css'
import Button from '../controls/Button.svelte'
import Image from '../structure/Image.svelte'

export interface LightboxImage {
  src: string
  alt: string
}

export interface LightboxMessages {
  close: string
  previous: string
  next: string
  position: (position: number, count: number) => string
}

export interface LightboxProps {
  /**
   * The picture shown first while the lightbox holds the position. Defaults to 0.
   */
  defaultIndex?: number
  defaultOpen?: boolean
  /**
   * The pictures in reading order. An empty list opens nothing.
   */
  images: LightboxImage[]
  /**
   * The picture shown, counted from 0. Controlled, as in Carousel.
   */
  index?: number
  /**
   * The dialog's accessible name, such as "Attachment preview". It is not drawn.
   */
  label: string
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: LightboxMessages
  /**
   * Called with the index of the picture the reader moved to.
   */
  onIndexChange?: (index: number) => void
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * A governed control, usually a Button, cloned to receive `onClick`, which also tells the
   * panel where it was opened from. As in Dialog.
   */
  trigger?: Snippet
}
</script>

<script lang="ts">
let {
  defaultIndex = 0,
  defaultOpen,
  images,
  index,
  label: labelOwn,
  messages = (() => ({
    close: 'Close',
    previous: 'Previous picture',
    next: 'Next picture',
    position: (position, count) => `${position} of ${count}`,
  }))(),
  onIndexChange,
  onOpenChange,
  open,
  trigger,
}: LightboxProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let opener = $state(null as HTMLElement | null)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultIndex)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
const within = $derived((at: number) => Math.min(Math.max(at, 0), Math.max(images.length - 1, 0)))
const shown = $derived(within(index ?? mirror))
const several = $derived(images.length > 1)
const current = $derived(images.slice(shown, shown + 1))
const travel = $derived((to: number) => {
  if (to < 0 || to >= images.length || to === shown) return
  mirror = to
  onIndexChange?.(to)
})
const keyDown = $derived((event: KeyboardEvent) => {
  if (!several || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return
  const rtl = getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl'
  const forward = rtl ? 'ArrowLeft' : 'ArrowRight'
  const back = rtl ? 'ArrowRight' : 'ArrowLeft'
  if (event.key !== forward && event.key !== back) return
  event.preventDefault()
  travel(event.key === forward ? shown + 1 : shown - 1)
})
const focusAfterMove = $derived(() => {
  if (panel === null) return
  const previous = panel.querySelector<HTMLButtonElement>('[data-lightbox-part="previous"] button')
  const next = panel.querySelector<HTMLButtonElement>('[data-lightbox-part="next"] button')
  const active = document.activeElement
  const lost =
    active === null ||
    active === document.body ||
    ((active === previous || active === next) && (active as HTMLButtonElement).disabled)
  if (!lost) return
  const other = [previous, next].find((button) => button !== null && !button.disabled)
  other?.focus()
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      open: open === undefined ? undefined : open && images.length > 0,
      defaultOpen: defaultOpen === undefined ? undefined : defaultOpen && images.length > 0,
      initialFocusEl: () => modalFocusTarget(panel, 'primary'),
      finalFocusEl: () => opener,
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const openFrom = $derived((event?: Event) => {
  if (images.length === 0) return
  if (event?.currentTarget instanceof HTMLElement) opener = event.currentTarget
  api.setOpen(true)
})
const scrimPresent = usePresence(
  () => api.open,
  () => scrim,
  'dialog.scrim',
)
const panelPresent = usePresence(
  () => api.open,
  () => panel,
  'dialog.panel',
)
const triggerScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({ onClick: openFrom }),
})
const effect1 = () => {
  focusAfterMove()
}
watchEffect(effect1, { watch: () => shown, mount: false })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Lightbox',
    element: () => panel,
    state: () => ({
      open: api.open,
      index: shown,
      images: images.map((image) => ({ alt: image.alt })),
    }),
    actions: {
      close: () => api.open && api.setOpen(false),
      next: () =>
        (() => {
          if (!api.open) throw new Error('The lightbox is closed.')
          if (shown === images.length - 1) throw new Error('This is the last picture.')
          travel(shown + 1)
        })(),
      previous: () =>
        (() => {
          if (!api.open) throw new Error('The lightbox is closed.')
          if (shown === 0) throw new Error('This is the first picture.')
          travel(shown - 1)
        })(),
    },
    withholds: () => panel,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<SlotOutlet scope={triggerScope} snippet={trigger}
  /><Portal
    >{#if scrimPresent.current
      }<div
        bind:this={scrim}
        {...attributes(mergeParts(api.getBackdropProps(), { onClick: () => { api.setOpen(false) } }))}
        class={styles.scrim}
        hidden={undefined}
      ></div
    >{/if
    }{#if panelPresent.current
      }<div {...attributes(api.getPositionerProps())} class={styles.positioner}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onKeydown: (event: KeyboardEvent) => { keyDown(event) } }))}
          class={styles.panel}
          hidden={undefined}
          data-member="lightbox"
          ><h2 {...attributes(api.getTitleProps())} class={styles.title}>{label}</h2
          ><div class={styles.stage}
            >{#each current as picture (shown)
              }<Image src={picture.src} alt={picture.alt} loading="eager"
            />{/each
          }</div
          >{#if several
            }<div class={styles.previous} data-lightbox-part="previous"
              ><Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="previous"
                label={messages.previous}
                disabled={shown === 0}
                onClick={() => { travel(shown - 1) }}
            /></div
            ><div class={styles.next} data-lightbox-part="next"
              ><Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="next"
                label={messages.next}
                disabled={shown === images.length - 1}
                onClick={() => { travel(shown + 1) }}
            /></div
            ><p class={styles.position} role="status"
              >{messages.position(shown + 1, images.length)
            }</p
          >{/if
          }<div class={styles.close} data-dialog-part="close"
            ><Button
              variant="ghost"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="close"
              label={messages.close}
              onClick={() => { api.setOpen(false) }}
          /></div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
